/// <summary>
///     AVA <c>initComponentwithBaseSalesLine</c> method.
/// </summary>
public void initComponentwithBaseSalesLine(BOM _bom)
{
    next initComponentwithBaseSalesLine(_bom);

    clsSalesLine.DEL_KCS_CustShipDateReq    = baseSalesLine.DEL_KCS_CustShipDateReq;
    clsSalesLine.ShippingDateRequested      = baseSalesLine.ShippingDateRequested;
    clsSalesLine.AVADispositionCodeId       = baseSalesLine.AVADispositionCodeId;
    clsSalesLine.KCS_BOSCommissCutPct       = baseSalesLine.KCS_BOSCommissCutPct;
}

/// <summary>
///     AVA <c>initComponentwithBaseSalesLine</c> method.
/// </summary>
/// <param name="_bom">
///     <c>BOM</c> as type
/// </param>
public void afterComponentWrite(BOM _bom)
{
    next afterComponentWrite(_bom);

    if(KCS_BOSSalesOrderCommissSplit::avaItemSetExistInventTransId(baseSalesLine.InventTransId))
    {
        KCS_BOSSalesOrderCommissSplit::avaItemSetCopySalesLine2SalesLine(   baseSalesLine.InventTransId, 
                                                                            clsSalesLine.InventTransId  );
    }
}

/// <summary>
///     AVA <c>afterCreateItemSetLines</c> method.
/// </summary>
public void afterCreateItemSetLines()
{
    next afterCreateItemSetLines();

    if(baseSalesId)
    {
        baseSalesLine.avaItemSetSetCommissionCutPctToComponents();

        SalesTable::AVAreorgLineNum(baseSalesId);
    }
}

/// <summary>
///     AVA <c>updateItemSetComponentsCheckFieldIds</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
boolean updateItemSetComponentsCheckFieldIds()
{
    boolean retVal;

    switch(clsSalesLineChangedFieldId)
    {
        case fieldNum(SalesLine, DEL_KCS_CustShipDateReq):
            clsSalesLineChanged = true;
            break;

        case fieldNum(SalesLine, AVADispositionCodeId):
            clsSalesLineChanged = true;
            break;

        case fieldNum(SalesLine, AVADispoDate):
            clsSalesLineChanged = true;
            break;

        default:
            break;
    }

    retVal = next updateItemSetComponentsCheckFieldIds();

    return retVal;
}

/// <summary>
///     AVA <c>updateItemSetComponentsUpdateFieldValue</c> method.
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
boolean updateItemSetComponentsUpdateFieldValue()
{
    boolean retVal;

    switch(clsSalesLineChangedFieldId)
    {
        case fieldNum(SalesLine, ReceiptDateConfirmed):
            clsSalesLine.DEL_KCS_CustShipDateReq    = baseSalesLine.DEL_KCS_CustShipDateReq;
            clsSalesLine.ShippingDateRequested      = baseSalesLine.ShippingDateRequested;
            retVal = true;
            break;

        case fieldNum(SalesLine, AVADispositionCodeId):
            clsSalesLine.AVADispositionCodeId       = baseSalesLine.AVADispositionCodeId;
            retVal = true;
            break;

        case fieldNum(SalesLine, AVADispoDate):
            clsSalesLine.AVADispoDate               = baseSalesLine.AVADispoDate;
            retVal = true;
            break;

        default:
            break;
    }
    retVal = next updateItemSetComponentsUpdateFieldValue();

    return retVal;
}
